# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""float_power_scalar_tensor_out: out[i] = base ** exponent[i].

Target constraint discovered on this backend (Triton 3.5.1 / flagtree
ascend3.5, Ascend 910B): there is no fp64 arithmetic, no fp64 load/store and no
float<->double cast (`hivm.hir.vcast` rejects double_to_float/float_to_double,
`hivm.hir.load/store` reject 64-bit float element types).  The reference
implementation (fp64 pow) therefore cannot run here, and the aten reference
itself computes the op in fp32 internally and widens the result into the fp64
`out` buffer ("Device do not support double dtype now, dtype cast replace with
float").

So the fp64 `out` is written as raw IEEE-754 bit patterns through a zero-copy
int32 view of the same storage (two 32-bit words per double), assembled with
int32-only shifts:

    hi_word = ((exp32 + 896) << 20) | (mant32 >> 3)
    lo_word = mant32 << 29

The power itself is the hardware vector exp2 on the fp32 exponent, which was
verified bit-identical to the aten-NPU reference over 65536 samples for every
tested exponent dtype (float16 / float32 / bfloat16 / int32).  Matching the
reference bit-for-bit is required: the reference carries up to ~1.8e-7 relative
fp32 error, i.e. more than the pytest rtol=1e-7, so an "exact" fp64-quality
result would be reported as a mismatch.
"""

import math

import torch
import triton
import triton.language as tl

BLOCK = 1024


@triton.jit
def _pow_scalar_tensor_kernel(
    e_ptr,
    o_ptr,
    n,
    log2b,
    BLOCK: tl.constexpr,
    POS_BASE: tl.constexpr,
):
    pid = tl.program_id(0)
    base = pid * BLOCK
    offs = base + tl.arange(0, BLOCK)
    mask = offs < n
    e = tl.load(e_ptr + offs, mask=mask, other=0).to(tl.float32)

    ri = tl.exp2(e * log2b).to(tl.int32, bitcast=True)
    mant = ri & 0x7FFFFF
    w_hi = (((ri >> 23) & 0xFF) + 896) << 20 | (mant >> 3)
    w_lo = mant << 29

    if not POS_BASE:
        # negative base: real only for integer exponents, sign = (-1)**e
        ev = e + 0.5
        ei = ev.to(tl.int32)
        ef = ei.to(tl.float32)
        ei = tl.where(ev < ef, ei - 1, ei)
        is_int = e == ei.to(tl.float32)
        odd = (ei & 1) != 0
        w_hi = tl.where(is_int & odd, w_hi ^ (-2147483648), w_hi)
        w_hi = tl.where(is_int, w_hi, 2146959360)
        w_lo = tl.where(is_int, w_lo, 0)

    words = tl.interleave(w_lo, w_hi)
    woffs = 2 * base + tl.arange(0, 2 * BLOCK)
    tl.store(o_ptr + woffs, words, mask=woffs < 2 * n)


def float_power_scalar_tensor_out(A, exponent, *extra, out=None):
    # out may be given by keyword (reference form) or positionally
    if out is None and extra:
        out = extra[0]
    if out is None:
        out = torch.empty(exponent.shape, dtype=torch.float64, device=exponent.device)
    elif out.dtype != torch.float64:
        raise RuntimeError(
            f"the output given to float_power has dtype {out.dtype} "
            "but the operation's result requires dtype Double"
        )
    elif out.shape != exponent.shape:
        out.resize_(exponent.shape)

    n = out.numel()
    if n == 0:
        return out

    base = float(A)
    if base == 2.0:
        log2b = 1.0
        pos_base = True
    else:
        pos_base = not (base < 0.0)
        mag = base if pos_base else -base
        log2b = -math.inf if mag == 0.0 else math.log2(mag)

    _pow_scalar_tensor_kernel[(triton.cdiv(n, BLOCK),)](
        exponent.reshape(-1),
        out.reshape(-1).view(torch.int32),
        n,
        log2b,
        BLOCK=BLOCK,
        POS_BASE=pos_base,
    )
    return out
